#![allow(clippy::needless_update)]
#![cfg(feature = "flow")]

use std::{
    fs::File,
    io::Read,
    path::{Path, PathBuf},
};

use swc_common::comments::SingleThreadedComments;
use swc_ecma_ast::*;
